class Envelope {
  struct Concept { virtual ~Concept() = default;
    virtual std::unique_ptr<Concept> clone() const = 0;
    virtual void draw() const = 0; };
  template <class T> struct Model final : Concept {     // any conforming letter
    T obj_;  explicit Model(T o) : obj_(std::move(o)) {}
    std::unique_ptr<Concept> clone() const override { return std::make_unique<Model>(*this); }
    void draw() const override { obj_.draw(); } };
  std::unique_ptr<Concept> impl_;                       // the letter, type-erased
 public:
  template <class T> Envelope(T x) : impl_(std::make_unique<Model<T>>(std::move(x))) {}
  void draw() const { impl_->draw(); }
};
